// Real native proof of Neo's JSON-only vendor policy. The frozen cache was
// generated by the pinned pre-policy core and positively loaded cache-only.
import assert from 'node:assert/strict';
import { readFile, readdir } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { loadModuleFactory } from './run-slice.mjs';

if (!process.argv[2]) throw new Error('usage: node vendor-cache-disabled-smoke.mjs <out/orca_slice.js>');
const fixture = resolve(import.meta.dirname, 'fixtures/compatibility-profiles');
const cache = await readFile(resolve(import.meta.dirname, 'fixtures/compatibility-vendor-cache.opc'));
const factory = await loadModuleFactory(resolve(process.argv[2]));
const Module = await factory({ noInitialRun: true, print: () => {}, printErr: () => {} });
const FS = Module.FS;
async function copy(directory, target) {
  FS.mkdirTree(target);
  for (const entry of await readdir(directory, { withFileTypes: true })) {
    if (entry.isDirectory()) await copy(join(directory, entry.name), `${target}/${entry.name}`);
    else FS.writeFile(`${target}/${entry.name}`, await readFile(join(directory, entry.name)));
  }
}
await copy(fixture, '/profiles');
FS.mkdirTree('/system');
for (const vendor of ['OrcaFilamentLibrary', 'CompatibilityFixture']) {
  FS.symlink(`/profiles/${vendor}.json`, `/system/${vendor}.json`);
  FS.symlink(`/profiles/${vendor}`, `/system/${vendor}`);
}
const cacheOpens = [];
const originalOpen = FS.open;
FS.open = function(path, ...args) {
  if (typeof path === 'string' && path.endsWith('.opc')) cacheOpens.push(path);
  return originalOpen.call(this, path, ...args);
};
function call(name, argTypes = [], args = []) {
  const pointer = Number(Module.ccall(name, 'number', argTypes, args));
  try { return JSON.parse(Module.UTF8ToString(pointer)); } finally { Module._free(pointer); }
}
function initialize() {
  const result = call('orc_init', ['string'], ['']);
  assert.equal(result.ok, true, JSON.stringify(result));
  const snapshot = call('orc_get_preset_snapshot');
  assert.equal(snapshot.ok, true, JSON.stringify(snapshot));
  return snapshot.printers.map(item => item.name);
}
const expected = ['Compatibility Alpha 0.4 nozzle', 'Compatibility Beta 0.4 nozzle'];
assert.deepEqual(initialize(), expected, 'complete JSON vendor loads through root/directory symlinks');
assert.equal(FS.readdir('/system').some(name => name.endsWith('.opc')), false, 'no cache is generated');

FS.writeFile('/system/CompatibilityFixture.opc', cache);
cacheOpens.length = 0; // The harness's intentional fixture write is not a native cache operation.
const manifest = FS.readFile('/profiles/CompatibilityFixture.json');
FS.writeFile('/profiles/CompatibilityFixture.json', '{invalid JSON');
assert.deepEqual(initialize(), [], 'a valid old cache cannot replace malformed source JSON');
assert.deepEqual(cacheOpens, [], 'native initialization never opens a cache');
FS.writeFile('/profiles/CompatibilityFixture.json', manifest);
assert.deepEqual(initialize(), expected, 'restored source JSON is authoritative despite the old cache');

FS.unlink('/system/CompatibilityFixture.json');
FS.unlink('/system/CompatibilityFixture');
assert.deepEqual(initialize(), [], 'cache-only discovery cannot revive the unlinked vendor');
assert.equal(FS.stat('/profiles/CompatibilityFixture.json').size, manifest.length, 'raw source remains available');
assert.deepEqual(cacheOpens, [], 'no native cache read or generation across reloads');
assert.deepEqual(FS.readdir('/system').filter(name => name.endsWith('.opc')), ['CompatibilityFixture.opc'],
  'only the deliberately injected cache exists');
console.log('vendor-cache-disabled smoke OK: JSON load, no cache IO/generation, malformed-source and cache-only rejection');
